                    []]
                input[1] = [file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/bed/test.bed',checkIfExists:true)]
                """
            }
        }
        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }
    }
}

